// what each sample has cost so far, in US dollars, in the order of DEMOS
const DEMO_SPENT = [1.27, 0.18, 0.46, 2.35, 0.62]

// a template not on screen yet when one is left, under an id of its own so it adds a bar; its cost
// is made up: a start that far back in the session's ledger, or the whole for a finished one
function demoPlan(now: number, shown: Plan[], usd: number | null): Plan {
  const titles = new Set(shown.map(p => p.title))
  const made = DEMOS.map((make, i) => ({ plan: make(now), spent: DEMO_SPENT[i] ?? 0.5 }))
  const fresh = made.filter(d => !titles.has(d.plan.title))
  const pool = fresh.length > 0 ? fresh : made
  const pick = pool[Math.floor(Math.random() * pool.length)] ?? made[0]!
  const isDone = pick.plan.state === 'done'
  return {
    ...pick.plan,
    id: `demo-${now.toString(36)}`,
    costStart: usd == null ? null : usd - pick.spent,
    cost: isDone ? pick.spent : null,
  }
}

// ---------- drawing ----------

type Where = { pos: number; total: number; stage: number; step: number; stageSize: number }

function where(p: Plan): Where {
  const steps = p.stages.flatMap((s, i) => s.steps.map((step, j) => ({ i, j, step })))
  const at = steps.findIndex(x => !isFinished(x.step.status))
  const pos = p.state === 'done' || at < 0 ? steps.length : at
  const cur = steps[Math.min(pos, steps.length - 1)]
  const stage = cur?.i ?? 0

  return { pos, total: steps.length, stage, step: pos >= steps.length ? (p.stages[stage]?.steps.length ?? 0) : (cur?.j ?? 0) + 1, stageSize: p.stages[stage]?.steps.length ?? 0 }
}

// the step at work: the active one, else the first not finished
function currentStep(p: Plan): PlanStep | undefined {
  const steps = p.stages.flatMap(s => s.steps)
  return steps.find(st => st.status === 'active') ?? steps.find(st => !isFinished(st.status))
}

// the knob's text colour on a fill: white, or near black on a fill too light for it
function inkOn(fill: string) {
  const [r, g, b] = hex(fill).map(v => {
    const c = v / 255
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4)
  })
  const lum = 0.2126 * (r ?? 0) + 0.7152 * (g ?? 0) + 0.0722 * (b ?? 0)
  // white while it keeps 3:1 (WCAG's floor for bold text), as on the default colours; dark past that
  return 1.05 / (lum + 0.05) >= 3 ? '#fff' : '#1c1b22'
}

const hex = (h: string) => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16))
const mix = (a: number[], b: number[], m: number) => a.map((v, i) => Math.round(v + ((b[i] ?? 0) - v) * m))
const rgb = (c: number[]) => `rgb(${c.join(',')})`
const esc = (s: string) => s.replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c] ?? c)
const hash = (a: number, b: number, k: number) => {
  const x = Math.sin(a * 127.1 + b * 311.7 + k * 74.7) * 43758.5453
  return x - Math.floor(x)
}
const textWidth = (s: string, px = 6.7) => [...s].reduce((w, ch) => w + (/[　-鿿]/.test(ch) ? 12 : /[ilI.,:;'|!]/.test(ch) ? 3.4 : /[mwMWШЩЖМ]/.test(ch) ? 9.5 : px), 0)

const ICON_PATH: Partial<Record<PlanState, string>> = {
  needs_input: 'M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3M12 17h.01',
  error: 'M18 6 6 18M6 6l12 12',
  done: 'M20 6 9 17l-5-5',
}

// last drawn head position per plan, so a redraw glides from where the bar was
const lastHead = new Map<string, number>()

function trackSvg(p: Plan, W: number): string {
  const H = TRACK_H
  const w = where(p)
  const done = p.state === 'done'
  // the fill is exactly the finished share: a fresh plan starts empty
  const frac = done ? 1 : Math.min(1, w.pos / Math.max(1, w.total))
  const fx = frac * W
  const key = p.id
  const from = lastHead.get(key) ?? fx
  lastHead.set(key, fx)

  const acc = hex(STATE_COLOR[p.state])
  const light = mix(acc, [255, 255, 255], 0.32)
  const grey = [132, 130, 138]
  const ease = 'calcMode="spline" keyTimes="0;1" keySplines=".2 .8 .2 1"'
  const glide = Math.abs(from - fx) > 0.5

  const bounds: number[] = []
  let acc2 = 0
  p.stages.forEach((s, i) => {
    acc2 += s.steps.length
    if (i < p.stages.length - 1) bounds.push((acc2 / w.total) * W)
  })

  // pixels: 3px grid, 7 rows, denser and closer to the state colour towards the head
  const buckets = [0, 1, 2, 3, 4].map(b => {
    const m = b / 4
    const dense = done ? 0.8 : 0.22 + 0.78 * Math.pow(m, 1.5)
    return { color: rgb(done ? light : mix(grey, light, m)), opacity: (0.35 + 0.65 * dense).toFixed(2) }
  })
  let px = ''
  for (let col = 0; col * 3 < fx; col++) {
    const x = col * 3
    const u = Math.min(1, (x + 1.5) / fx)
    const dense = done ? 0.8 : 0.22 + 0.78 * Math.pow(u, 1.5)
    const bucket = done ? 4 : Math.min(4, Math.floor(Math.min(1, Math.pow(u, 0.9) * 1.1) * 4.99))
    for (let r = 0; r < 7; r++) {
      if (hash(col, r, 1) > dense + 0.1) continue
      px += `<rect x="${x}" y="${1 + r * 3}" class="b${bucket} t${Math.floor(hash(col, r, 2) * 4)}"/>`
    }
  }

  let marks = ''
  let k = 0
  p.stages.forEach((s, i) => {
    s.steps.forEach((_, j) => {
      if (k > 0) {
        const x = (k / w.total) * W
        const isStage = j === 0
        // stage boundaries are full-height lines, steps are short ticks; bright once passed
        const passed = x < fx - 1
        const h = isStage ? H : 8
        const fill = passed ? rgb(mix(light, [255, 255, 255], 0.45)) : '#8A8984'
        const opacity = passed ? (isStage ? 0.95 : 0.6) : isStage ? 0.7 : 0.45
        marks += `<rect x="${(x - (isStage ? 1 : 0.75)).toFixed(1)}" y="${(H - h) / 2}" width="${isStage ? 2 : 1.5}" height="${h}" rx=".75" fill="${fill}" opacity="${opacity}"/>`
      }
      k++
    })
    void i
  })

  // knob: a pill with stage and count, or a round dot with the stage number when narrow
  const isNarrow = W < NARROW
  const color = STATE_COLOR[p.state]
  // the knob's text and icon: white on a dark fill, near black on a light one (pastel palettes)
  const ink = inkOn(color)
  const icon = ICON_PATH[p.state]
  const single = p.stages.length === 1
  const number = single ? Math.min(w.total, w.pos + 1) : w.stage + 1
  let knob = ''
  let kw = H
  if (isNarrow) {
    const label = done ? '' : String(number)
    knob = `<circle cx="0" cy="${H / 2}" r="${H / 2}" fill="${color}"/>${
      done ? `<path d="${ICON_PATH.done}" transform="translate(-6 5) scale(.5)" fill="none" stroke="${ink}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>` : `<text x="0" y="${H / 2 + 4.2}" text-anchor="middle" class="kt">${label}</text>`
    }`
  } else {
    // one stage (a todo list): the step at work names the knob; several: the stage at work
    const name = done ? L().done : single ? (currentStep(p)?.title ?? p.stages[0]?.name ?? L().tasks) : (p.stages[w.stage]?.name ?? '')
    const agents = p.agents ?? []
    const base = p.id === AGENTS ? `${w.pos}/${w.total}` : done ? `${w.total}/${w.total}` : single ? `${number}/${w.total}` : `${w.step}/${w.stageSize}`
    const agentCount = agents.length > 0 && p.id !== AGENTS ? ` · ${agents.filter(a => a.state === 'done').length}/${agents.length} agents` : ''
    const count = base + agentCount
    const iconW = icon ? 16 : 0
    const countW = textWidth(count, 6.5)
    const maxW = Math.max(80, W * 0.55)
    let shown = name
    while (shown.length > 3 && 20 + iconW + textWidth(shown) + 6 + countW > maxW) shown = shown.slice(0, -1)
    if (shown !== name) shown = shown.trimEnd() + '…'
    kw = Math.round(20 + iconW + textWidth(shown) + 6 + countW)
    const left = -kw / 2 + 10
    knob = `<rect x="${-kw / 2}" y="0" width="${kw}" height="${H}" rx="${H / 2}" fill="${color}"/>`
    if (icon) knob += `<path d="${icon}" transform="translate(${left} 5) scale(.5)" fill="none" stroke="${ink}" stroke-width="3.6" stroke-linecap="round" stroke-linejoin="round"/>`
    knob += `<text x="${left + iconW}" y="${H / 2 + 4.2}" class="kt">${esc(shown)}<tspan class="kc" dx="6">${count}</tspan></text>`
  }
  const clampX = (x: number) => Math.max(kw / 2, Math.min(W - kw / 2, x))
  const kx = clampX(fx)
  const kFrom = clampX(from)

  const style = `<style>
.b0{fill:${buckets[0]?.color};fill-opacity:${buckets[0]?.opacity}}.b1{fill:${buckets[1]?.color};fill-opacity:${buckets[1]?.opacity}}
.b2{fill:${buckets[2]?.color};fill-opacity:${buckets[2]?.opacity}}.b3{fill:${buckets[3]?.color};fill-opacity:${buckets[3]?.opacity}}
.b4{fill:${buckets[4]?.color};fill-opacity:${buckets[4]?.opacity}}
rect[class]{width:2px;height:2px}
.t0,.t1,.t2,.t3{animation:tw ${done ? 3.2 : 2.2}s ease-in-out infinite}
.t1{animation-duration:${done ? 3.8 : 2.8}s;animation-delay:-.7s}.t2{animation-duration:${done ? 4.4 : 1.9}s;animation-delay:-1.3s}.t3{animation-duration:${done ? 3.5 : 3.3}s;animation-delay:-.4s}
@keyframes tw{0%,100%{opacity:1}50%{opacity:${done ? 0.8 : 0.45}}}
.kt{font:500 12px 'Anthropic Sans',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;fill:${ink}}
.kc{font-weight:400;fill-opacity:.75}
@media (prefers-reduced-motion:reduce){.t0,.t1,.t2,.t3{animation:none}}
</style>`
  const glideFill = glide ? `<animate attributeName="width" from="${from.toFixed(1)}" to="${fx.toFixed(1)}" dur=".45s" ${ease} fill="freeze"/>` : ''
  const glideKnob = glide ? `<animateTransform attributeName="transform" type="translate" from="${kFrom.toFixed(1)} 0" to="${kx.toFixed(1)} 0" dur=".45s" ${ease} fill="freeze"/>` : ''

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${style}
<defs><clipPath id="pill"><rect width="${W}" height="${H}" rx="${H / 2}"/></clipPath><clipPath id="fill"><rect width="${fx.toFixed(1)}" height="${H}">${glideFill}</rect></clipPath>
<linearGradient id="base" x1="0" x2="${fx.toFixed(1)}" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="${rgb(acc)}" stop-opacity="${done ? 0.3 : 0.05}"/><stop offset="1" stop-color="${rgb(acc)}" stop-opacity=".33"/></linearGradient></defs>
<g clip-path="url(#pill)"><rect width="${W}" height="${H}" fill="#808080" fill-opacity=".16"/>
<g clip-path="url(#fill)"><rect width="${fx.toFixed(1)}" height="${H}" fill="url(#base)"/>${px}</g>${marks}</g>
<g transform="translate(${kx.toFixed(1)} 0)">${glideKnob}${knob}</g></svg>`
}

const AGENT_COLOR: Record<AgentRun['state'], string> = {
  running: STATE_COLOR.running,
  waiting: STATE_COLOR.needs_input,
  done: STATE_COLOR.done,
  error: STATE_COLOR.error,
}

function applyPalette(name: PaletteName | undefined) {
  const p = palette(name)
  Object.assign(STATE_COLOR, { running: p.running, needs_input: p.waiting, error: p.error, done: p.done })
  Object.assign(AGENT_COLOR, { running: p.running, waiting: p.waiting, error: p.error, done: p.done })
}

const elapsed = (ms: number) => {
  const sec = Math.max(0, Math.round(ms / 1000))
  return sec < 60 ? `${sec}s` : `${Math.floor(sec / 60)}m ${sec % 60}s`
}

// which strips show: all of a small batch; in a big one the unfinished first, the rest folded into one line
function visibleAgents(p: Plan, now: number): { shown: AgentRun[]; hidden: AgentRun[] } | null {
  const list = p.agents ?? []
  if (list.length === 0) return null
  const hasError = list.some(a => a.state === 'error')
  if (p.agentsDoneAt && now - p.agentsDoneAt > FOLD_MS && !hasError) return null
  if (list.length <= MAX_STRIPS) return { shown: list, hidden: [] }
  const keep = new Set(list.filter(a => a.state !== 'done').slice(0, MAX_STRIPS - 1).map(a => a.id))
  for (const a of [...list].reverse()) {
    if (keep.size >= MAX_STRIPS - 1) break
    keep.add(a.id)
  }
  return { shown: list.filter(a => keep.has(a.id)), hidden: list.filter(a => !keep.has(a.id)) }
}

// what each strip showed last time it was drawn, so a change morphs from the old status instead of jumping
const lastStrip = new Map<string, { tool: string; color: string }>()
const MORPH = '.2s'

const stripsHeight = (n: number) => n * STRIP_H + (n - 1) * STRIP_GAP

// one tinted strip per agent: state colour, name, what it does now and for how long; not a progress bar
function stripsSvg(v: { shown: AgentRun[]; hidden: AgentRun[] }, W: number, now: number): string {
  const isNarrow = W < NARROW
  const rows: string[] = []
  v.shown.forEach((a, i) => {
    const c = AGENT_COLOR[a.state]
    const y = i * (STRIP_H + STRIP_GAP)
    const indent = a.depth > 0 ? 12 : 0
    let px = ''
    if (a.state === 'running') {
      for (let col = 0; col * 3 < W; col++) {
        for (let r = 0; r < 4; r++) {
          if (hash(col + i * 41, r, 5) > 0.2) continue
          px += `<rect x="${col * 3}" y="${y + 3 + r * 3.6}" class="t${Math.floor(hash(col, r, 6) * 4)}" fill="${c}" fill-opacity=".32"/>`
        }
      }
    }
    const nameRoom = isNarrow ? W - 30 - indent : W * 0.5
    let name = (a.depth > 0 ? '↳ ' : '') + a.title
    while (name.length > 4 && textWidth(name, 6.2) > nameRoom) name = name.slice(0, -1)
    if (name !== (a.depth > 0 ? '↳ ' : '') + a.title) name = name.trimEnd() + '…'
    const nameX = 19 + indent
    const toolX = nameX + textWidth(name, 6.2) + 8
    const time = elapsed((a.endedAt ?? now) - a.startedAt)
    // a status change: the old word blurs out while the new one blurs in, and the tint flows to the new colour
    const was = lastStrip.get(a.id)
    lastStrip.set(a.id, { tool: a.tool, color: c })
    const isToolChanged = was !== undefined && was.tool !== a.tool
    const flow = (attr: string) => (was && was.color !== c ? `<animate attributeName="${attr}" from="${was.color}" to="${c}" dur="${MORPH}" fill="freeze"/>` : '')
    const tool = isNarrow
      ? ''
      : (isToolChanged ? `<text x="${toolX}" y="${y + 12.5}" class="sn mo" style="fill:${was.color}">${esc(was.tool)}</text>` : '') +
        `<text x="${toolX}" y="${y + 12.5}" class="sn${isToolChanged ? ' mi' : ''}" style="fill:${c}">${esc(a.tool)}</text>` +
        `<text x="${W - 9}" y="${y + 12.5}" text-anchor="end" class="sn st">${time}</text>`
    rows.push(
      `<rect x="0" y="${y}" width="${W}" height="${STRIP_H}" rx="${STRIP_H / 2}" fill="${c}" fill-opacity=".15">${flow('fill')}</rect>${px}` +
        `<circle cx="${10 + indent}" cy="${y + STRIP_H / 2}" r="3" fill="${c}"${a.state === 'running' ? ' class="sd"' : ''}>${flow('fill')}</circle>` +
        `<text x="${nameX}" y="${y + 12.5}" class="sn">${esc(name)}</text>` +
        tool,
    )
  })
  if (v.hidden.length > 0) {
    const y = v.shown.length * (STRIP_H + STRIP_GAP)
    const doneCount = v.hidden.filter(a => a.state === 'done').length
    rows.push(
      `<rect x="0" y="${y}" width="${W}" height="${STRIP_H}" rx="${STRIP_H / 2}" fill="#808080" fill-opacity=".14"/>` +
        `<text x="10" y="${y + 12.5}" class="sn st">${esc(L().moreAgents(v.hidden.length))} · ${esc(L().nDone(doneCount))}</text>`,
    )
  }
  return `<style>.sn{font:400 11.5px 'Anthropic Sans',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;fill:#F0EEFC}.st{fill-opacity:.65}
.sd{animation:sp 1.1s ease-in-out infinite}@keyframes sp{50%{opacity:.3}}
.mi{animation:mi ${MORPH} ease-out both}@keyframes mi{from{opacity:0;filter:blur(3px)}}
.mo{animation:mo ${MORPH} ease-in both}@keyframes mo{to{opacity:0;filter:blur(3px)}}
@media (prefers-reduced-motion:reduce){.sd,.mi,.mo{animation:none}.mo{opacity:0}}</style>${rows.join('')}`
}

function plural(n: number, word: string) {
  return `${n} ${word}${n === 1 ? '' : 's'}`
}

// ---------- engine glue ----------

// the engine's player first (afplay on macOS); PowerShell where it cannot play
function play($: EngineInterface, name: 'decision' | 'error' | 'done') {
  if (soundTheme === 'off') return
  const file = `${$.plugin.root}/sounds/${soundTheme}/${name}.wav`.replace(/\//g, '\\')
  void $.audio.play({ asset: `sounds/${soundTheme}/${name}.wav` }).catch(() =>
    $.process
      .run(['powershell', '-NoLogo', '-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-Command', `(New-Object Media.SoundPlayer '${file}').PlaySync()`], { timeoutMs: 5000 })
      .catch(() => undefined),
  )
}

// the agents bar is the mod's own; the model never owes it an update
const AGENTS = 'agents:auto' // slug() never yields ':', so no model id can take it
const isOpenPlan = (p: Plan) => p.id !== AGENTS && p.state === 'running' && !p.stages.flatMap(s => s.steps).every(s => isFinished(s.status))

const slug = (s: string) =>
  s
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 40) || 'plan'

// adds or replaces one bar by id; keeps at most MAX_BARS, dropping finished ones first
// computed inside update() from the latest list, so concurrent writers (parallel agents) do not drop each other
function placeBar(list: readonly Plan[], next: Plan): Plan[] {
  const prev = list.find(p => p.id === next.id)
  // an update keeps its row; a new bar goes to the bottom
  const rest = prev ? list.map(p => (p.id === next.id ? next : p)) : [...list, next]
  while (rest.length > MAX_BARS) {
    const doneAt = rest.findIndex(p => p.state === 'done')
    rest.splice(doneAt >= 0 ? doneAt : 0, 1)
  }
  return rest
}

function chime($: EngineInterface, prev: PlanState | undefined, next: PlanState) {
  if (next === prev) return
  if (next === 'needs_input') play($, 'decision')
  if (next === 'error') play($, 'error')
  if (next === 'done') play($, 'done')
}

async function putPlan($: EngineInterface, next: Plan) {
  let prev: Plan | undefined
  const usd = await sessionUsd($)
  await update($, plans, list => {
    prev = list.find(p => p.id === next.id)
    // the cost runs from the bar's opening; it is fixed when the bar first turns done
    const costStart = prev ? (prev.costStart ?? null) : (next.costStart ?? usd)
    const isDoneNow = next.state === 'done' && prev?.state !== 'done'
    const cost = next.cost ?? (isDoneNow && costStart != null && usd != null ? usd - costStart : (prev?.cost ?? null))
    return placeBar(list, { ...next, costStart, cost: next.state === 'done' ? cost : null })
  })
  chime($, prev?.state, next.state)
  if (!prev) await update($, isOpen, () => true)
}

// an amount as two lines, the figure and then its currency: "2,53 $" or "$2.53" -> ["2,53", "$"]
function splitCurrency(amount: string) {
  if (!amount) return []
  const figure = amount.replace(/\s*\$\s*/, '')
  return [figure, '$']
}

// a bar's cost: fixed once it is done, else the session's cost since it opened; null under half a cent
function spentOn(p: Plan, usdNow: number | null) {
  const spent = p.state === 'done' ? p.cost : p.costStart != null && usdNow != null ? usdNow - p.costStart : null
  return spent != null && spent >= 0.005 ? spent : null
}

// what the session has cost so far in US dollars, or null where the host keeps no ledger
async function sessionUsd($: EngineInterface) {
  const usage = await $.session.usage()
  return typeof usage.cost?.usd === 'number' ? usage.cost.usd : null
}

// ---------- agents: drawn from engine events alone, no model calls ----------
// each subagent lives on a bar as one state strip: the open task bar it was started under,
// the bar of its parent agent, or the mod's own "Agents" bar when no task is open.
// Module maps: a reload forgets running agents, whose strips then stay until the bar is closed.
const agentHome = new Map<string, string>() // agentId -> bar id
const toolUses = new Map<string, string>() // tool_use_id -> agentId, to find who waits on a permission
const waiting = new Set<string>()
let foldUntil = 0 // keep ticking until finished strips have folded

// the mod's own bar mirrors its agents as steps, finished first, so percent and count read done/total
function syncAuto(p: Plan, now: number): Plan {
  const agents = p.agents ?? []
  const isOver = agents.length > 0 && agents.every(a => a.state === 'done' || a.state === 'error')
  const agentsDoneAt = isOver ? (p.agentsDoneAt ?? now) : null
  if (p.id !== AGENTS) return { ...p, agentsDoneAt }
  const rank = (a: AgentRun) => (a.state === 'done' ? 0 : a.state === 'error' ? 1 : 2)
  const steps: PlanStep[] = [...agents]
    .sort((a, b) => rank(a) - rank(b))
    .map(a => ({ title: a.title, status: a.state === 'done' ? 'done' : a.state === 'error' ? 'error' : 'active', substeps: [] }))
  const state: PlanState = isOver
    ? agents.some(a => a.state === 'error') ? 'error' : 'done'
    : agents.some(a => a.state === 'waiting') ? 'needs_input' : 'running'
  return { ...p, agentsDoneAt, stages: [{ name: 'Agents', steps }], state }
}

function addRun(p: Plan, run: AgentRun, parentId: string | undefined, now: number): Plan {
  // a batch that has finished makes room for the next one
  const list = p.agentsDoneAt ? [] : [...(p.agents ?? [])]
  let at = list.length
  const parentAt = parentId ? list.findIndex(a => a.id === parentId) : -1
  if (parentAt >= 0) {
    at = parentAt + 1
    while (at < list.length && (list[at]?.depth ?? 0) > 0) at++
  }
  list.splice(at, 0, run)
  return syncAuto({ ...p, agents: list, agentsDoneAt: null }, now)
}

// changes one agent's strip inside the latest list; sounds follow the bar's state
async function editAgent($: EngineInterface, agentId: string, change: (a: AgentRun) => AgentRun) {
  const home = agentHome.get(agentId)
  if (!home) return
  const now = await $.clock.now()
  let before: PlanState | undefined
  let after: PlanState | undefined
  let isFolding = false
  await update($, plans, list =>
    list.map(p => {
      if (p.id !== home || !p.agents?.some(a => a.id === agentId)) return p
      before = p.state
      const next = syncAuto({ ...p, agents: p.agents.map(a => (a.id === agentId ? change(a) : a)) }, now)
      after = next.state
      isFolding = !p.agentsDoneAt && next.agentsDoneAt !== null
      return next
    }),
  )
  if (isFolding) foldUntil = now + FOLD_MS + 1500
  if (before !== undefined && after !== undefined) chime($, before, after)
}

async function dropPlan($: EngineInterface, id: string) {
  lastHead.delete(id)
  for (const p of await read($, plans)) if (p.id === id) for (const a of p.agents ?? []) lastStrip.delete(a.id)
  await update($, plans, list => list.filter(p => p.id !== id))
}

const STEP_SCHEMA = {
  type: 'object',
  required: ['title', 'status'],
  properties: {
    title: { type: 'string' },
    status: { enum: STATUSES },
    substeps: {
      type: 'array',
      items: { type: 'object', required: ['title', 'status'], properties: { title: { type: 'string' }, status: { enum: STATUSES } } },
    },
  },
}

// only calls that change something count as work for the enforcement below; reading and searching are free
const WORK_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit', 'Bash', 'PowerShell'])
const WORK_BEFORE_PLAN = 3 // the 4th changing call without a plan is refused once
const CALLS_BEFORE_NUDGE = 6 // working calls without a plan update before a reminder


export function registerPlanProgress(on: Parameters<Register>[0], options: { enforcement?: Enforcement; language?: string; sounds?: SoundTheme; palette?: PaletteName }) {
  applyPalette(options.palette)
  enforcement = options.enforcement ?? 'soft'
  soundTheme = options.sounds ?? 'soft'
  language = options.language ?? 'auto'
  // a matcher, so other features may hook session.start too
  on('session.start', { isInteractive: [true, false] }, async ($, e, next) => {
    await startPlanProgress($)
    return next(e)
  })

  // the bars sit above whatever the hooks beneath draw
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const bars = await planBars($, e)
    const rest = await next(e)
    return stack($.ui.resolve(e).Box, [['plan-bars', bars], ['below-plans', rest]]) ?? rest
  })

  // per-turn bookkeeping; module variables are fine here, a reload just starts a fresh count
  let workCalls = 0
  let sinceUpdate = 0
  let isPlanTouched = false
  let hasRefused = false
  let isWaitingOnBackground = false

  on('turn.start', async ($, e, next) => {
    workCalls = 0
    sinceUpdate = 0
    isPlanTouched = false
    hasRefused = false
    isWaitingOnBackground = false

    return next(e)
  })

  // the rule lives in the cached system prompt; a message only carries one short line when bars are open,
  // and the person answering clears any "needs input" without a model call
  on('prompt.submit', async ($, e, next) => {
    if (e.origin.kind !== 'composer') return next(e)
    const list = await read($, plans)
    if (list.some(p => p.state === 'needs_input')) {
      await update($, plans, all => all.map(p => (p.state === 'needs_input' ? { ...p, state: 'running' as const, note: null } : p)))
    }
    const open = list.filter(p => p.state !== 'done' && p.id !== AGENTS)
    if (open.length === 0) return next(e)
    const line = `still-mods open bars: ${open
      .map(p => {
        const w = where(p)
        return `${p.id} (${p.stages[w.stage]?.name ?? ''} ${w.step}/${w.stageSize})`
      })
      .join(', ')}`

    return next({ ...e, context: [...(e.context ?? []), line] })
  })

  // watches the main loop's changing calls: refuses once when multi-step work starts without a bar,
  // and reminds to update the bar when it goes stale mid-turn
  on('tool.call', async ($, e, next) => {
    // a subagent's call only names its current tool on its strip; no gate, no reminders
    if (e.agentId) {
      const agentId = e.agentId
      if (!agentHome.has(agentId)) return next(e)
      await editAgent($, agentId, a => ({ ...a, state: 'running', tool: e.tool }))
      if (e.tool_use_id) toolUses.set(e.tool_use_id, agentId)
      const ran = await next(e)
      if (e.tool_use_id) toolUses.delete(e.tool_use_id)
      if (waiting.delete(agentId)) await editAgent($, agentId, a => (a.state === 'waiting' ? { ...a, state: 'running' } : a))
      return ran
    }
    if (!WORK_TOOLS.has(e.tool)) return next(e)
    isWaitingOnBackground = (e as unknown as Raw).run_in_background === true
    const hasLivePlan = isPlanTouched || (await read($, plans)).some(isOpenPlan)
    const asksForBar = enforcement !== 'off' && !hasLivePlan && !hasRefused && workCalls >= WORK_BEFORE_PLAN
    if (asksForBar) {
      hasRefused = true
      if (enforcement === 'strict') return { deny: `still-mods: several changes ahead. Create a bar with ${TOOL} first, then retry.` }
    }
    const ran = await next(e)
    // a shell call that only read (ls, git status, grep) is not work
    if (ran.deny !== undefined || ran.isReadOnly) return ran
    workCalls += 1
    sinceUpdate += 1
    // soft: the call ran, and the model is told once that a bar would fit
    if (asksForBar) return { ...ran, context: [...(ran.context ?? []), `still-mods: several changes ahead, consider a bar with ${TOOL}.`] }
    if (enforcement !== 'off' && hasLivePlan && sinceUpdate >= CALLS_BEFORE_NUDGE) {
      sinceUpdate = 0

      return { ...ran, context: [...(ran.context ?? []), `still-mods: bar is stale, send {id, next:true} or {id, done, active}.`] }
    }

    return ran
  })

  // an open bar at the end of a turn: a question to the user marks it waiting on its own;
  // only a turn that did work and left the bar unexplained is sent back once
  on('classic.Stop', async ($, e, next) => {
    const result = await next(e)
    if (e.stop_hook_active || result.block || isWaitingOnBackground || (e.background_tasks?.length ?? 0) > 0) return result
    const open = (await read($, plans)).filter(isOpenPlan)
    if (open.length === 0) return result
    const asks = /\?\s*$/.test(e.last_assistant_message ?? '')
    if (asks) {
      const last = open[open.length - 1]
      if (last) await putPlan($, { ...last, state: 'needs_input' })

      return result
    }
    // only strict sends the turn back; soft and off leave the open bar as it is
    if (enforcement !== 'strict' || (workCalls === 0 && !isPlanTouched)) return result

    return {
      ...result,
      block: `still-mods: ${open.map(p => p.id).join(', ')} still open. Update each with ${TOOL}: {id, next:true}, or state "done", "needs_input" or "error" with a note.`,
    }
  })


  on('prompt.compose', async ($, e, next) => {
    const result = await next(e)

    return { sections: [...result.sections, { id: 'still-mods:rules', text: rules(), scope: 'session' as const }] }
  })

  on('tool.call', { tool: TOOL }, async ($, e) => {
    const raw = e as unknown as Raw
    const now = await $.clock.now()
    const list = await read($, plans)
    const id = slug(str(raw.id, 60) || str(raw.title, 80))
    const next = normalize(raw, list.find(p => p.id === id) ?? null, now, id)
    if (next.stages.length === 0) return { deny: `plan_progress: no bar "${id}" yet; create it with title and stages.` }
    isPlanTouched = true
    sinceUpdate = 0
    await putPlan($, next)
    const w = where(next)

    const active = next.stages.flatMap(st => st.steps).find(st => st.status === 'active')

    return { result: `${id}: ${Math.min(w.pos, w.total)}/${w.total}, ${next.state}${active ? `, active "${active.title}"` : ''}` }
  })

  on('tool.call', { tool: 'AskUserQuestion' }, async ($, e, next) => {
    const live = (await read($, plans)).filter(p => p.state === 'running').pop()
    if (live) await update($, plans, list => list.map(p => (p.id === live.id ? { ...p, state: 'needs_input' as const } : p)))
    play($, 'decision')
    const ran = await next(e)
    if (live) await update($, plans, list => list.map(p => (p.id === live.id && p.state === 'needs_input' ? { ...p, state: 'running' as const } : p)))

    return ran
  })

  on('tool.call', { tool: 'ExitPlanMode' }, async ($, e, next) => {
    play($, 'decision')
    const ran = await next(e)
    const text = ran.deny === undefined && ran.isError !== true ? (ran.result as { plan?: unknown } | undefined)?.plan : undefined
    if (typeof text === 'string') {
      const parsed = parsePlan(text, await $.clock.now())
      if (parsed) await putPlan($, { ...parsed, id: slug(parsed.title) })
    }

    return ran
  })

  on('command.run', { command: 'still-mods-progress' }, async $ => {
    if ((await read($, plans)).length === 0) return { text: 'No plan yet. /still-mods-progress-demo shows a sample.' }
    const open = await read($, isOpen)
    await update($, isOpen, () => !open)

    return { text: open ? 'Progress bars hidden.' : 'Progress bars shown.' }
  })

  on('command.run', { command: 'still-mods-progress-demo' }, async $ => {
    await putPlan($, demoPlan(await $.clock.now(), await read($, plans), await sessionUsd($)))
    await update($, isOpen, () => true)

    return { text: locale === 'fr' ? 'Barre d’exemple ajoutée au-dessus du prompt.' : 'Sample bar added above the prompt.' }
  })

  on('command.run', { command: 'still-mods-progress-clear' }, async $ => {
    await update($, plans, () => [])

    return { text: 'Progress bars removed.' }
  })

  on('command.run', { command: 'still-mods-progress-sounds' }, async $ => {
    play($, 'decision')
    $.clock.after(900, () => play($, 'error'))
    $.clock.after(1800, () => play($, 'done'))

    if (soundTheme === 'off') return { text: locale === 'fr' ? 'Sons coupés (/still-mods sounds soft pour les remettre).' : 'Sounds are off (/still-mods sounds soft turns them on).' }
    return { text: locale === 'fr' ? `Sons (${soundTheme}) : décision, erreur, terminé.` : `Sounds (${soundTheme}): decision, error, done.` }
  })

  // always drawn, so the person sees the mod is loaded; dim while there is nothing to show
  on('ui.render', { component: 'SessionMode' }, async ($, e, next) => {
    const count = (await read($, plans)).length
    const open = await read($, isOpen)
    const { Box, Button } = $.ui.resolve(e)
    // other mods add their labels to modes beneath us; keep them
    const below = await next(e)
    const press = () =>
      count === 0
        ? $.ui.toast(L().pluginOn)
        : update($, isOpen, () => !open)

    return (
      <Box flexDirection="row" alignItems="center" gap={1}>
        <Button key="progress-toggle" dimColor={count === 0 || !open} label={count > 1 ? `${L().progress} ${count}` : L().progress} onPress={press} />
        {below}
      </Box>
    )
  })



  on('agent.spawn', async ($, e, next) => {
    const started = await next(e)
    if (!('agentId' in started) || !started.agentId) return started
    const id = started.agentId
    const now = await $.clock.now()
    const parentHome = e.parentAgentId ? agentHome.get(e.parentAgentId) : undefined
    const home = parentHome ?? [...(await read($, plans))].reverse().find(isOpenPlan)?.id ?? AGENTS
    agentHome.set(id, home)
    const run: AgentRun = {
      id,
      title: (e.description || e.subagentType).slice(0, 60),
      state: 'running',
      tool: 'Starting',
      startedAt: now,
      endedAt: null,
      depth: parentHome ? 1 : 0,
    }
    let isNew = false
    await update($, plans, list => {
      if (list.some(p => p.id === home)) return list.map(p => (p.id === home ? addRun(p, run, e.parentAgentId, now) : p))
      isNew = true
      const auto: Plan = { id: AGENTS, title: 'Agents', kind: 'todo', stages: [], state: 'running', note: null, startedAt: now }
      return placeBar(list, addRun(auto, run, undefined, now))
    })
    if (isNew) await update($, isOpen, () => true)

    return started
  })

  // an agent waiting on a permission prompt turns its strip amber until the call goes on
  on('tool.check', async ($, e, next) => {
    const verdict = await next(e)
    const agentId = e.tool_use_id ? toolUses.get(e.tool_use_id) : undefined
    const useId = e.tool_use_id
    // the mode often settles an ask by itself in a blink; only a call still held after a moment waits on the person
    if (agentId && useId && verdict.decision === 'ask') {
      $.clock.after(600, async () => {
        if (toolUses.get(useId) !== agentId) return
        waiting.add(agentId)
        await editAgent($, agentId, a => ({ ...a, state: 'waiting', tool: L().needsApproval }))
      })
    }

    return verdict
  })

  on('turn.complete', async ($, e, next) => {
    const agentId = e.agentId
    if (agentId && agentHome.has(agentId)) {
      const now = await $.clock.now()
      const isFailed = e.reason !== 'answer'
      const tool = e.reason === 'aborted' ? L().stopped : isFailed ? L().failed : L().done
      await editAgent($, agentId, a => ({ ...a, state: isFailed ? 'error' : 'done', tool, endedAt: now }))
      // the mod's own bar sounds through its state; a strip on a task bar sounds here
      if (isFailed && agentHome.get(agentId) !== AGENTS) play($, 'error')
      agentHome.delete(agentId)
      waiting.delete(agentId)
    }
    // a plan whose steps are all finished closes itself
    for (const p of await read($, plans)) {
      if (p.id === AGENTS) continue
      if (p.state === 'done') continue
      const steps = p.stages.flatMap(s => s.steps)
      if (steps.length > 0 && steps.every(s => isFinished(s.status))) await putPlan($, { ...p, state: 'done' })
    }

    return next(e)
  })
}

// what the plan bars need at each session.start
export async function startPlanProgress($: EngineInterface) {
  const settings = await $.settings.read()
  locale = resolveLocale(language, settings.language, systemLocale())
  await $.tool.register({
    name: 'plan_progress',
    description: 'Live progress bar above the prompt, one per id. Create with title + stages; update with short ops (next, done, active, failed) or state.',
    inputSchema: {
      type: 'object',
      required: ['id'],
      properties: {
        id: { type: 'string', description: 'Bar id; reuse it for updates' },
        title: { type: 'string' },
        kind: { enum: ['plan', 'todo'] },
        stages: {
          type: 'array',
          description: 'Full breakdown, only when creating or restructuring',
          items: { type: 'object', required: ['name', 'steps'], properties: { name: { type: 'string' }, steps: { type: 'array', items: STEP_SCHEMA } } },
        },
        next: { type: 'boolean', description: 'Active step finished, start the next one' },
        done: { type: 'array', items: { type: 'string' }, description: 'Step titles now finished' },
        active: { type: 'string', description: 'Step title now in progress' },
        failed: { type: 'string', description: 'Step title that failed' },
        state: { enum: ['running', 'needs_input', 'error', 'done'] },
        note: { type: 'string', description: 'One line for needs_input or error' },
      },
    },
  })
  $.clock.every(1000, async () => {
    if (agentHome.size > 0 || (await $.clock.now()) < foldUntil) await update($, tick, n => n + 1)
  })
  await $.command.register({ name: 'still-mods-progress', description: 'Show or hide the progress bars' })
  await $.command.register({ name: 'still-mods-progress-demo', description: 'Show a sample plan in the progress bars' })
  await $.command.register({ name: 'still-mods-progress-sounds', description: 'Play the decision, error and done sounds' })
  await $.command.register({ name: 'still-mods-progress-clear', description: 'Remove all progress bars' })
}

// the plan bars, or null when there are none to show
export async function planBars($: EngineInterface, e: any): Promise<any> {
  const list = await read($, plans)
  if (list.length === 0 || e.props.hasSurvey || !(await read($, isOpen))) return null
  const t = $.ui.resolve(e)
  const { Box, Button, Text } = t
  const Svg = 'Svg' in t ? t.Svg : null
  const total = Math.max(320, (e.props.bodyColumns || 100) * 8)
  // every bar has the same width and is pinned to the right edge (fixed-width percent, close button),
  // so rows line up whatever their titles; the slack goes into the gap after the title.
  // Desktop reports ~8 CSS px per column; glyph, gaps, percent and the close button take ~126 px.
  const titleWidth = Math.min(Math.round(total * 0.3), Math.max(...list.map(p => Math.round(textWidth(p.title, 6.4)))))
  await read($, tick)
  const usdNow = await sessionUsd($)
  // the cost column: as wide as the widest amount, kept on one line and right-aligned, its room taken
  // from the track so every row still lines up
  const costs = list.map(p => spentOn(p, usdNow)).map(v => (v == null ? '' : formatUsd(locale, v)))
  const oneLine = Math.max(0, ...costs.map(c => [...c].length))
  // too narrow for the amounts on one line: the figure above, the currency under it
  const isTight = oneLine > 0 && total - titleWidth - 140 - (oneLine * 8 + 8) < 120
  const costLines = costs.map(c => (isTight ? splitCurrency(c) : [c]))
  const costCells = Math.max(0, ...costLines.flat().map(c => [...c].length))
  const costPx = costCells > 0 ? costCells * 8 + 8 : 0
  const trackW = Math.max(120, Math.min(1400, total - titleWidth - 140 - costPx))
  const now = await $.clock.now()
  // a hairline between task bars, so each bar and its agent strips read as one group
  const divider = `<svg xmlns="http://www.w3.org/2000/svg" width="${total}" height="1"><rect width="${total}" height="1" fill="#808080" fill-opacity=".22"/></svg>`

  return (
    <Box flexDirection="column" gap={1}>
      {list.flatMap((p, i) => {
        const v = visibleAgents(p, now)
        const stripsH = v ? 5 + stripsHeight(v.shown.length + (v.hidden.length > 0 ? 1 : 0)) : 0
        const source = v
          ? `<svg xmlns="http://www.w3.org/2000/svg" width="${trackW}" height="${TRACK_H + stripsH}">${trackSvg(p, trackW)}<g transform="translate(0 ${TRACK_H + 5})">${stripsSvg(v, trackW, now)}</g></svg>`
          : trackSvg(p, trackW)
        const agentsAlt = v ? `; agents: ${(p.agents ?? []).map(a => `${a.title} ${a.state}`).join(', ')}` : ''
        const line = i > 0 && Svg ? [<Svg key={`div-${p.id}`} source={divider} alt="" width={total} height={1} />] : []
        const w = where(p)
        const pct = p.state === 'done' ? 100 : Math.round((Math.min(w.pos, w.total) / Math.max(1, w.total)) * 100)
        const color = STATE_COLOR[p.state]
        const stageName = (p.stages.length === 1 ? currentStep(p)?.title : undefined) ?? p.stages[w.stage]?.name ?? ''
        const alt =
          p.state === 'done'
            ? `${p.title}: done, ${plural(w.total, 'step')}`
            : `${p.title}: ${stageName}, step ${w.step} of ${w.stageSize}, ${pct}%${p.note ? ` — ${p.note}` : ''}${agentsAlt}`
        const bar = `${'━'.repeat(Math.round(pct / 4))}${'─'.repeat(25 - Math.round(pct / 4))}`

        return [
          ...line,
          <Box key={`bar-${p.id}`} flexDirection="row" alignItems={v ? 'flex-start' : 'center'} gap={1}>
            <Text color={color}>{STATE_GLYPH[p.state]}</Text>
            <Text wrap="truncate">{p.title}</Text>
            <Box flexGrow={1} />
            {Svg ? (
              <Svg source={source} alt={alt} width={trackW} height={TRACK_H + stripsH} />
            ) : (
              <Text>
                <Text color={color}>{bar.replace(/─/g, '')}</Text>
                <Text dimColor>{bar.replace(/━/g, '')}</Text>
                <Text color={color}>{` ${stageName} ${w.step}/${w.stageSize}`}</Text>
              </Text>
            )}
            {costCells > 0 ? (
              <Box key={`cost-${p.id}`} width={costCells} flexShrink={0} flexDirection="column" alignItems="flex-end">
                {(costLines[i] ?? []).map((line, n) => (
                  <Text key={`cost-${p.id}-${n}`} dimColor wrap="truncate">
                    {line}
                  </Text>
                ))}
              </Box>
            ) : null}
            <Text dimColor>{`${String(pct).padStart(3, FIGURE_SPACE)}%`}</Text>
            <Button key={`close-${p.id}`} plain dimColor label="✕" onPress={() => dropPlan($, p.id)} />
          </Box>,
        ]
      })}
    </Box>
  )
}

files.features/settings.ts:
// The /still-mods command: lists every option of the plugin with its value, and changes one, for
// surfaces with no /config menu (the desktop Code tab). A change goes through $.config.set when the
// option is a row of the config menu; a plugin loaded from a folder has no row there in the desktop
// app, so the command then writes pluginConfigs in ~/.claude/settings.json itself and touches a file
// of the plugin, which makes the watched folder reload it with the new options.
import type { EngineInterface, Register } from 'claude-code'

import { type Locale, resolveLocale, systemLocale } from './i18n'
import { PALETTE_NAMES } from './palettes'

const COMMAND = 'still-mods'
const PLUGIN = 'still-mods'
// written after a change so the watched folder reloads the plugin; ignored by git
const RELOAD_STAMP = '.reload-stamp'

type Field = { name: string; kind: 'boolean' | 'choice' | 'text' | 'number'; choices?: string[]; fallback: string | boolean | number; label: Record<Locale, string> }

// the manifest's userConfig, in the order the list shows it
const FIELDS: Field[] = [
  { name: 'planProgress', kind: 'boolean', fallback: true, label: { en: 'Plan progress bars', fr: 'Barres de progression des plans' } },
  {
    name: 'planEnforcement',
    kind: 'choice',
    choices: ['strict', 'soft', 'off'],
    fallback: 'soft',
    label: { en: 'How hard Claude is held to its bars', fr: 'Exigence envers Claude sur les barres' },
  },
  {
    name: 'sounds',
    kind: 'choice',
    choices: ['soft', 'classic', 'off'],
    fallback: 'soft',
    label: { en: 'Sounds for decision, error, done', fr: 'Sons de décision, erreur, fin' },
  },
  { name: 'turnNotify', kind: 'boolean', fallback: true, label: { en: 'Sound and toast when a long turn ends', fr: 'Son et notification à la fin d’un long tour' } },
  { name: 'turnNotifySeconds', kind: 'number', fallback: 60, label: { en: 'Seconds a turn must last to notify', fr: 'Durée minimale du tour pour notifier (s)' } },
  { name: 'gitStatus', kind: 'boolean', fallback: true, label: { en: 'Git status line (branch, changes, ahead/behind)', fr: 'Ligne d’état git (branche, modifs, avance/retard)' } },
  { name: 'cacheMeter', kind: 'boolean', fallback: true, label: { en: 'Prompt cache column (hit rate, time left)', fr: 'Colonne cache (taux, temps restant)' } },
  { name: 'cacheTtl', kind: 'choice', choices: ['1h', '5m'], fallback: '1h', label: { en: 'Prompt cache lifetime', fr: 'Durée de vie du cache' } },
  { name: 'usageMeters', kind: 'boolean', fallback: true, label: { en: 'Context and limit meters', fr: 'Compteurs de contexte et de limites' } },
  {
    name: 'palette',
    kind: 'choice',
    choices: PALETTE_NAMES,
    fallback: 'default',
    label: { en: 'Colours of the bars and meters', fr: 'Couleurs des barres et compteurs' },
  },
  { name: 'language', kind: 'choice', choices: ['auto', 'en', 'fr'], fallback: 'auto', label: { en: 'Labels language', fr: 'Langue des libellés' } },
  { name: 'timeZone', kind: 'text', fallback: 'Europe/Paris', label: { en: 'Reset time zone (IANA)', fr: 'Fuseau des heures de reset (IANA)' } },
]

const TEXT = {
  en: {
    title: 'still-mods options',
    change: `Change one: /${COMMAND} <option> <value>, e.g. /${COMMAND} usageMeters off`,
    commands: `Commands: /${COMMAND}-progress (show or hide the bars), /${COMMAND}-progress-demo, /${COMMAND}-progress-clear, /${COMMAND}-progress-sounds`,
    unknown: (f: string) => `Unknown option "${f}".`,
    needs: (f: string, v: string) => `"${f}" takes ${v}.`,
    notChanged: (f: string, why: string) => `${f} not changed: ${why}`,
    changed: (f: string, v: string) => `${f} = ${v}. The plugin reloads with it.`,
    written: (f: string, v: string, path: string) => `${f} = ${v}, saved in ${path}. The plugin reloads with it.`,
    noWrite: (f: string, v: string, why: string) =>
      `${f} could not be saved (${why}). Set it in ~/.claude/settings.json:\n"pluginConfigs": { "${PLUGIN}": { "options": { "${f}": ${v} } } }`,
    anyText: 'any text',
  },
  fr: {
    title: 'Options de still-mods',
    change: `Pour changer : /${COMMAND} <option> <valeur>, ex. /${COMMAND} usageMeters off`,
    commands: `Commandes : /${COMMAND}-progress (afficher ou masquer les barres), /${COMMAND}-progress-demo, /${COMMAND}-progress-clear, /${COMMAND}-progress-sounds`,
    unknown: (f: string) => `Option inconnue « ${f} ».`,
    needs: (f: string, v: string) => `« ${f} » accepte ${v}.`,
    notChanged: (f: string, why: string) => `${f} inchangé : ${why}`,
    changed: (f: string, v: string) => `${f} = ${v}. Le mod se recharge avec cette valeur.`,
    written: (f: string, v: string, path: string) => `${f} = ${v}, enregistré dans ${path}. Le mod se recharge avec cette valeur.`,
    noWrite: (f: string, v: string, why: string) =>
      `${f} n'a pas pu être enregistré (${why}). Règle-le dans ~/.claude/settings.json :\n"pluginConfigs": { "${PLUGIN}": { "options": { "${f}": ${v} } } }`,
    anyText: 'un texte',
  },
}

// the values this load runs with, from register(on, options)
let current: Record<string, unknown> = {}
let locale: Locale = 'en'

export function registerSettings(on: Parameters<Register>[0], options: Record<string, unknown>) {
  current = options

  // a matcher, so other features may hook session.start too
  on('session.start', { isInteractive: [true, false] }, async ($, e, next) => {
    const settings = await $.settings.read()
    locale = resolveLocale(current.language, settings.language, systemLocale())
    await $.command.register({
      name: COMMAND,
      description: locale === 'fr' ? 'Afficher ou changer les options de still-mods' : 'Show or change the still-mods options',
      argumentHint: '[' + FIELDS.map(f => f.name).join('|') + '] [value]',
    })
    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    const [name, ...rest] = e.args.trim().split(/\s+/).filter(Boolean)
    if (!name) return { text: await describe($) }
    return { text: await change($, name, rest.join(' ')) }
  })
}

// this plugin's rows of the config menu, keyed `<plugin>.<field>` (`<plugin>@inline.<field>` loaded from a folder)
async function ownRows($: EngineInterface) {
  const rows = await $.config.list()
  return rows
    .filter(row => row.key.startsWith(PLUGIN + '.') || row.key.startsWith(PLUGIN + '@'))
    .map(row => ({ ...row, field: row.key.slice(row.key.lastIndexOf('.') + 1) }))
}

function accepted(field: Field) {
  if (field.kind === 'boolean') return 'on | off'
  if (field.kind === 'choice') return (field.choices ?? []).join(' | ')
  if (field.kind === 'number') return locale === 'fr' ? 'un nombre' : 'a number'
  return TEXT[locale].anyText
}

async function describe($: EngineInterface) {
  const rows = await ownRows($)
  const width = Math.max(...FIELDS.map(f => f.name.length))
  const lines = FIELDS.map(field => {
    const row = rows.find(r => r.field === field.name)
    const value = row ? row.value : (current[field.name] ?? field.fallback)
    return `  ${field.name.padEnd(width)}  ${formatValue(value).padEnd(12)}  ${field.label[locale]}  (${accepted(field)})`
  })
  const T = TEXT[locale]
  return [T.title, ...lines, '', T.change, T.commands].join('\n')
}

async function change($: EngineInterface, name: string, raw: string) {
  const T = TEXT[locale]
  const field = FIELDS.find(f => f.name.toLowerCase() === name.toLowerCase())
  if (!field) return `${T.unknown(name)}\n\n${await describe($)}`
  const value = parseValue(field, raw)
  if (value === undefined) return T.needs(field.name, accepted(field))
  const row = (await ownRows($)).find(r => r.field === field.name)
  if (!row) {
    try {
      const path = await saveOption($, field.name, value)
      current = { ...current, [field.name]: value }
      return T.written(field.name, formatValue(value), path)
    } catch (error) {
      return T.noWrite(field.name, JSON.stringify(value), error instanceof Error ? error.message : String(error))
    }
  }
  const result = await $.config.set({ key: row.key, value })
  if (result.deny) return T.notChanged(field.name, result.deny)
  return T.changed(field.name, formatValue(result.value))
}

// writes pluginConfigs.<plugin>.options.<name> in the user settings, keeping every other key, then
// touches the reload stamp so the watched plugin folder loads again with the new options
async function saveOption($: EngineInterface, name: string, value: string | boolean | number) {
  const home = (await $.env.get('USERPROFILE')) ?? (await $.env.get('HOME'))
  if (!home) throw new Error('no home directory')
  const path = home.replace(/\\/g, '/') + '/.claude/settings.json'
  const text = (await $.fs.exists(path)) ? await $.fs.read(path) : '{}'
  const settings = JSON.parse(text) as Record<string, any>
  const configs = (settings.pluginConfigs ??= {})
  const own = (configs[PLUGIN] ??= {})
  own.options = { ...(own.options ?? {}), [name]: value }
  await $.fs.write(path, JSON.stringify(settings, null, 2) + '\n')
  await $.fs.write(`${$.plugin.root}/${RELOAD_STAMP}`, new Date().toISOString() + '\n')
  return path
}

function parseValue(field: Field, raw: string): string | boolean | number | undefined {
  const word = raw.trim()
  if (field.kind === 'number') {
    const n = Number(word.replace(',', '.'))
    return word && Number.isFinite(n) && n >= 0 ? n : undefined
  }
  if (field.kind === 'boolean') {
    const w = word.toLowerCase()
    if (['on', 'true', 'yes', 'oui', '1'].includes(w)) return true
    if (['off', 'false', 'no', 'non', '0'].includes(w)) return false
    return undefined
  }
  if (field.kind === 'choice') return field.choices?.find(c => c === word.toLowerCase())
  return word || undefined
}

function formatValue(value: unknown) {
  if (value === true) return 'on'
  if (value === false) return 'off'
  return String(value)
}

files.features/usage-meters.tsx:
import type { EngineInterface, Register } from 'claude-code'

import { stack } from './band'
import { palette, type PaletteName } from './palettes'
import { formatUsd, type Locale, resolveLocale, strings, systemLocale } from './i18n'

// Usage meters: context, 5-hour and weekly limit usage, adapted from usage-meter by HolyGrail
// (https://github.com/HolyGrail/claude-mods): see NOTICE.

let context: any = null
// what the session has cost so far, in US dollars; null where the host keeps no ledger
let costUsd: number | null = null
let rateLimits: any[] = []
// when rateLimits was last measured, in $.clock.now() milliseconds
let measuredAt = 0
let ticker: { cancel(): void } | null = null
// this session's own key in the store
let ownKey: string | null = null

// rate limits are per account, so sessions share readings through $.store and each shows the newest;
// each session writes only its own key, so no write can overwrite another session's reading
const KEY_PREFIX = 'reading:'
const HOUR_MS = 3_600_000
// readings older than the longest window say nothing current
const STALE_MS = 8 * 24 * HOUR_MS
// the session.end reasons after which the meters stop; /clear, /resume and logout keep them running
const FINAL_REASONS = ['prompt_input_exit', 'other']
const TICK_MS = 60_000
// reset times are shown in this zone, the timeZone option
let timeZone = 'Europe/Paris'
// the labels' language: the language option, else read at session.start
let language = 'auto'
let locale: Locale = 'en'

// title: a key of the labels, or the label itself; showsDay adds the weekday to the reset time
// divisions: the bar is cut in that many equal parts, one per hour or per day of the window
const WINDOWS: Record<string, { title: string; ms?: number; showsDay?: boolean; divisions?: number }> = {
  five_hour: { title: 'fiveHour', ms: 5 * HOUR_MS, divisions: 5 },
  seven_day: { title: 'sevenDay', ms: 7 * 24 * HOUR_MS, showsDay: true, divisions: 7 },
  spend_limit: { title: '$' },
}
// the context bar's cuts: every tenth from half full, where the window starts to matter
const CONTEXT_TICKS = [0.5, 0.6, 0.7, 0.8, 0.9]
// shown even before any reading, so the band keeps its shape from the first frame
const ALWAYS_SHOWN = ['five_hour', 'seven_day']

// pace thresholds: margin is the elapsed share of the window minus the used share
const GREEN_MIN_MARGIN = 10
const RED_BELOW_MARGIN = -15
const GREEN_MAX_USED = 10
const RED_MIN_USED = 90

// the narrowest a meter's column gets, in terminal cells
const MIN_BAR_CELLS = 12
// the desktop draws about this many CSS pixels per column
const PX_PER_COLUMN = 8
const METER_GAP = 3
const BAND_RESERVED_COLUMNS = 2
const SVG_BAR_HEIGHT = 12
// set from the palette option when the module registers
let usesPalette = false
const SVG_COLORS: Record<string, string> = { success: '#4caf50', warning: '#e0a526', error: '#e5534b', track: 'rgba(128,128,128,0.3)', marker: '#5b9bff', tick: 'rgba(0,0,0,0.38)' }
const MARKER_COLOR = 'cyan'
// the hover card's background: a raw colour close to the band's in the app's dark theme (a theme key
// the surface does not know makes it refuse the whole band)
const CARD_BACKGROUND = '#2b2b2b'
const CARD_MIN_CELLS = 40

type Meter = {
  key: string
  label: string
  used: number | undefined
  elapsed: number | null
  detail: string
  ticks?: number[]
  // a figure and a colour of their own, where the bar measures something else (the cache)
  percent?: string
  status?: string | null
  barStatus?: string
  // the lines of the card shown over the meter while the pointer is on it
  card?: string[]
}

// the main thread's prompt cache: the share of the last response's input it served, and when that
// response came, from which the cache's time to live runs; kept per session in the store
let cacheTtlMs = HOUR_MS
// the cacheMeter option
let cacheShown = true
let cacheRate: number | null = null
let lastResponseAt: number | null = null
let cacheKey: string | null = null
const CACHE_PREFIX = 'cache:'
// the cache counts as nearly gone in the last part of its life
const CACHE_LOW_SHARE = 0.15

// session.start fires again on a reload: the store stays, these variables start over
async function startUsageMeters($: EngineInterface) {
  const settings = await $.settings.read()
  locale = resolveLocale(language, settings.language, systemLocale())
  ticker?.cancel()
  rateLimits = []
  measuredAt = 0
  ownKey = KEY_PREFIX + (await $.session.id())
  await loadCache($)
  const usage: any = await $.session.usage()
  context = usage.context
  costUsd = typeof usage.cost?.usd === 'number' ? usage.cost.usd : null
  if (usage.rateLimits.length > 0) await publishSnapshot($, usage.rateLimits)
  await refresh($)
  ticker = $.clock.every(TICK_MS, async () => {
    await refresh($)
    $.ui.invalidate('ui.render')
  })
  $.ui.invalidate('ui.render')
}

export function registerUsageMeters(on: Parameters<Register>[0], options: { timeZone?: string; language?: string; palette?: PaletteName; cacheTtl?: '5m' | '1h'; cacheMeter?: boolean }) {
  cacheTtlMs = options.cacheTtl === '5m' ? 5 * 60_000 : HOUR_MS
  cacheShown = options.cacheMeter !== false
  const p = palette(options.palette)
  usesPalette = (options.palette ?? 'default') !== 'default'
  Object.assign(SVG_COLORS, { success: p.success, warning: p.warning, error: p.danger, track: p.track, marker: p.marker })
  if (options.timeZone) timeZone = options.timeZone
  language = options.language ?? 'auto'

  // the meters sit below whatever the hooks beneath draw, next to the prompt
  // a matcher, so other features may hook session.start too
  on('session.start', { isInteractive: [true, false] }, async ($, e, next) => {
    await startUsageMeters($)
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const rest = await next(e)
    const meters = await usageMeters($, e)
    return stack($.ui.resolve(e).Box, [['above-meters', rest], ['usage-meters', meters]]) ?? rest
  })
  on('session.end', async ($, e, next) => {
    if (!FINAL_REASONS.includes(e.reason) || !ownKey) return next(e)
    ticker?.cancel()
    await releaseKey($)
    return next(e)
  })

  // /clear, /resume, /branch and compaction change the context; all but compaction switch session id
  on('classic.SessionStart', { source: ['clear', 'resume', 'fork', 'compact'] }, async ($, e, next) => {
    const key = KEY_PREFIX + (await $.session.id())
    if (ownKey && key !== ownKey) {
      await releaseKey($)
      ownKey = key
    }
    context = ((await $.session.usage()) as any).context
    const since = (e as unknown as { seconds_since_last_response?: number }).seconds_since_last_response
    if (typeof since === 'number') await saveCache($, cacheRate, (await $.clock.now()) - since * 1000)
    $.ui.invalidate('ui.render')
    return next(e)
  })

  // each response of the main thread: how much of its input the cache served, and the time it came
  on('turn.step', { turnId: /^/ }, async function* ($, e, next) {
    const result = yield* next(e)
    const usage = result.usage
    if (!e.agentId && usage) {
      const input = usage.input_tokens + usage.cache_read_input_tokens + usage.cache_creation_input_tokens
      await saveCache($, input > 0 ? (usage.cache_read_input_tokens / input) * 100 : cacheRate, await $.clock.now())
      $.ui.invalidate('ui.render')
    }
    return result
  })

  on('session.measure', async ($, e, next) => {
    context = e.context
    if (typeof e.cost?.usd === 'number') costUsd = e.cost.usd
    if (e.changed.includes('rateLimits')) await remember($, e.rateLimits as any[])
    $.ui.invalidate('ui.render')
    return next(e)
  })
}

async function usageMeters($: EngineInterface, e: any): Promise<any> {
  const elements: any = $.ui.resolve(e)
  const now = await $.clock.now()
  const L = strings(locale)
  const meters: Meter[] = [{ key: 'ctx', label: L.ctx, used: context?.percent, elapsed: null, detail: contextDetail(), ticks: CONTEXT_TICKS, card: contextCard() }]
  if (cacheShown) meters.push(cacheMeter(now))
  for (const limit of rateLimits) meters.push(readLimit(limit, now))
  // the windows arrive with the first API response; until then they show as unknown
  for (const kind of ALWAYS_SHOWN) {
    if (!rateLimits.some(l => l.kind === kind)) meters.push({ key: kind, label: titleOf(kind), used: undefined, elapsed: null, detail: L.waiting, card: [windowTitle(kind), L.cardWaiting] })
  }
  const columns = e.props.bodyColumns ?? 0
  const room = columns - BAND_RESERVED_COLUMNS
  // as many meters on a row as fit whole, their title, figure and detail untruncated; the rows
  // balanced (4 meters as 2 + 2, not 3 + 1), down to one per row on a phone
  const need = Math.max(MIN_BAR_CELLS, ...meters.map(widthOf))
  const fit = Math.max(1, Math.min(meters.length, Math.floor((room + METER_GAP) / (need + METER_GAP))))
  const rowCount = Math.ceil(meters.length / fit)
  const perRow = Math.ceil(meters.length / rowCount)
  const cells = Math.max(MIN_BAR_CELLS, Math.floor((room - METER_GAP * (perRow - 1)) / perRow))
  const gauge = 'Svg' in elements ? 'svg' : 'text'
  const rows = Array.from({ length: rowCount }, (_, r) => meters.slice(r * perRow, (r + 1) * perRow))
  // equal columns from edge to edge, each two lines: the figures, then the bar
  return elements.Box({
    key: 'usage-meters',
    flexDirection: 'column',
    rowGap: 1,
    children: rows.map((row, r) =>
      elements.Box({ key: `meters-row-${r}`, flexDirection: 'row', columnGap: METER_GAP, children: row.map(m => meter(elements, gauge, cells, m)) }),
    ),
  })
}

async function remember($: EngineInterface, limits: any[]) {
  // take the time first, so a refresh meanwhile cannot pair old limits with it
  const now = await $.clock.now()
  rateLimits = limits
  measuredAt = now
  if (ownKey) await $.store.set(ownKey, { at: now, limits })
}

// takes the newest reading any session saved, unless this session's own is newer still
async function refresh($: EngineInterface) {
  const { entries, newest } = await scan($)
  if (newest && newest.reading.at >= measuredAt) {
    rateLimits = newest.reading.limits
    measuredAt = newest.reading.at
  } else if (!newest && measuredAt < (await $.clock.now()) - STALE_MS) {
    rateLimits = []
    measuredAt = 0
  }
  await prune($, entries, newest?.key)
}

// keeps this session's reading marked ended if it is the newest, removes it otherwise
async function releaseKey($: EngineInterface) {
  if (!ownKey) return
  const { entries, newest } = await scan($)
  if (newest?.key === ownKey) await $.store.set(ownKey, { ...newest.reading, ended: true })
  else await $.store.delete(ownKey)
  await prune($, entries, newest?.key)
}

async function prune($: EngineInterface, entries: { key: string; reading: any }[], newestKey: string | undefined) {
  const cutoff = (await $.clock.now()) - STALE_MS
  for (const { key, reading } of entries) {
    if (key === ownKey || key === newestKey) continue
    if (!isReading(reading) || reading.ended === true || reading.at < cutoff) await $.store.delete(key)
  }
}

// a shared reading always wins over the startup snapshot of usage(), which may be older
async function publishSnapshot($: EngineInterface, snapshot: any[]) {
  const { newest } = await scan($)
  if (newest) {
    rateLimits = newest.reading.limits
    measuredAt = newest.reading.at
    return
  }
  await remember($, snapshot)
}

async function scan($: EngineInterface) {
  const entries: { key: string; reading: any }[] = []
  let newest: { key: string; reading: any } | null = null
  const cutoff = (await $.clock.now()) - STALE_MS
  for (const key of await $.store.keys()) {
    if (!key.startsWith(KEY_PREFIX)) continue
    const reading: any = await $.store.get(key)
    entries.push({ key, reading })
    if (!isReading(reading) || reading.at < cutoff) continue
    if (!newest || reading.at > newest.reading.at || (reading.at === newest.reading.at && key > newest.key)) newest = { key, reading }
  }
  return { entries, newest }
}

function isReading(value: any) {
  return value != null && typeof value.at === 'number' && Array.isArray(value.limits)
}

function readLimit(limit: any, now: number): Meter {
  const window = WINDOWS[limit.kind]
  const label = titleOf(limit.kind)
  const resetsAtMs = limit.resetsAt == null ? null : Date.parse(limit.resetsAt)
  // a window that has reset since the last reading starts again from zero
  if (resetsAtMs != null && resetsAtMs <= now) return { key: limit.kind, label, used: 0, elapsed: window?.ms ? 0 : null, detail: '', ticks: divisionPoints(window?.divisions) }
  const elapsed = window?.ms && resetsAtMs != null ? clamp(100 - ((resetsAtMs - now) / window.ms) * 100) : null
  const detail = resetsAtMs == null ? '' : strings(locale).resetsIn(untilReset(resetsAtMs - now)) + ' · ' + resetClock(resetsAtMs, window?.showsDay === true)
  const card = limitCard(limit.kind, limit.percentUsed, elapsed, resetsAtMs, now)
  return { key: limit.kind, label, used: limit.percentUsed, elapsed, detail, ticks: divisionPoints(window?.divisions), card }
}

// what a limit's card says: the window, the share used against the time gone and what that pace
// means, the reset, and how to read the bar
function limitCard(kind: string, used: number, elapsed: number | null, resetsAtMs: number | null, now: number) {
  const L = strings(locale)
  const lines = [windowTitle(kind)]
  if (elapsed != null) {
    const margin = elapsed - used
    const pace = margin >= GREEN_MIN_MARGIN ? 'under' : margin < RED_BELOW_MARGIN ? 'over' : 'near'
    lines.push(`${L.cardUsed(Math.round(used) + '%', Math.round(elapsed) + '%')} · ${L.cardPace[pace]}`)
  } else {
    lines.push(Math.round(used) + '%')
  }
  if (resetsAtMs != null) lines.push(L.cardReset(resetClock(resetsAtMs, WINDOWS[kind]?.showsDay === true), untilReset(resetsAtMs - now)))
  if (kind === 'five_hour') lines.push(L.cardTicksHours)
  if (kind === 'seven_day') lines.push(L.cardTicksDays)
  return lines
}

function windowTitle(kind: string) {
  const L = strings(locale)
  return kind === 'five_hour' ? L.cardFiveHour : kind === 'seven_day' ? L.cardSevenDay : titleOf(kind)
}

// what the context's card says: the tokens in the window, the session's cost, the cuts
function contextCard() {
  const L = strings(locale)
  if (!context?.window) return [L.cardCtxNone]
  const pct = typeof context.percent === 'number' ? Math.round(context.percent) + '%' : '—'
  const tokens = typeof context.tokens === 'number' ? formatTokens(context.tokens) : '—'
  const lines = [L.cardCtx(tokens, formatTokens(context.window), pct)]
  if (costUsd != null) lines.push(L.cardCost(formatUsd(locale, costUsd)))
  lines.push(L.cardCtxTicks)
  return lines
}

// the cache column: its hit rate as the figure, the time it has left as the bar, which drains
function cacheMeter(now: number): Meter {
  const L = strings(locale)
  const rate = cacheRate == null ? '—' : Math.round(cacheRate) + '%'
  const rateStatus = cacheRate == null ? null : cacheRate >= 80 ? 'success' : cacheRate >= 50 ? 'warning' : 'error'
  const tokens = typeof context?.tokens === 'number' ? formatTokens(context.tokens) : null
  if (lastResponseAt == null) return { key: 'cache', label: L.cache, used: undefined, elapsed: null, detail: L.waiting, percent: rate, status: rateStatus, card: [L.cardCacheNone] }
  const at = resetClock(lastResponseAt, false)
  const left = lastResponseAt + cacheTtlMs - now
  if (left <= 0) {
    const card = [L.cardCacheRate(rate), L.cardCacheCold(at), ...(tokens ? [L.cardCacheNext(tokens)] : [])]
    return { key: 'cache', label: L.cache, used: 0, elapsed: null, detail: L.cold, percent: rate, status: rateStatus, card }
  }
  const share = (left / cacheTtlMs) * 100
  const card = [L.cardCacheRate(rate), L.cardCacheWarm(at, resetClock(lastResponseAt + cacheTtlMs, false), untilReset(left)), ...(tokens ? [L.cardCacheNext(tokens)] : [])]
  return {
    card,
    key: 'cache',
    label: L.cache,
    used: share,
    elapsed: null,
    detail: L.warm(untilReset(left)),
    percent: rate,
    status: rateStatus,
    // the bar's own colour: green while it has time, orange near the end
    barStatus: share / 100 <= CACHE_LOW_SHARE ? 'warning' : 'success',
  }
}

async function loadCache($: EngineInterface) {
  cacheKey = CACHE_PREFIX + (await $.session.id())
  const saved: any = await $.store.get(cacheKey)
  cacheRate = typeof saved?.rate === 'number' ? saved.rate : null
  lastResponseAt = typeof saved?.at === 'number' ? saved.at : null
  // other sessions' readings past any cache's life say nothing; their keys go
  const cutoff = (await $.clock.now()) - 2 * HOUR_MS
  for (const key of await $.store.keys()) {
    if (!key.startsWith(CACHE_PREFIX) || key === cacheKey) continue
    const other: any = await $.store.get(key)
    if (typeof other?.at !== 'number' || other.at < cutoff) await $.store.delete(key)
  }
}

async function saveCache($: EngineInterface, rate: number | null, at: number) {
  cacheRate = rate
  lastResponseAt = at
  if (cacheKey) await $.store.set(cacheKey, { rate, at })
}

function titleOf(kind: string) {
  const title = WINDOWS[kind]?.title ?? kind
  const L = strings(locale) as Record<string, unknown>
  return typeof L[title] === 'string' ? (L[title] as string) : title
}

// the session's cost, then the tokens in the window and its size: 3,42 $ · 210k / 1M
function contextDetail() {
  const cost = costUsd == null ? '' : formatUsd(locale, costUsd)
  const tokens = contextTokens()
  return cost && tokens ? `${cost} · ${tokens}` : cost || tokens
}

function contextTokens() {
  if (!context?.window) return ''
  const used = typeof context.tokens === 'number' ? context.tokens : typeof context.percent === 'number' ? (context.percent / 100) * context.window : null
  return used == null ? formatTokens(context.window) : formatTokens(used) + ' / ' + formatTokens(context.window)
}

function formatTokens(n: number) {
  if (n >= 1_000_000) return String(Math.round(n / 100_000) / 10) + 'M'
  if (n >= 1000) return Math.round(n / 1000) + 'k'
  return String(Math.round(n))
}

function statusOf(used: number, elapsed: number | null) {
  if (used >= RED_MIN_USED) return 'error'
  if (elapsed == null) return used >= 80 ? 'error' : used >= 50 ? 'warning' : 'success'
  const margin = elapsed - used
  if (margin < RED_BELOW_MARGIN) return 'error'
  if (margin < GREEN_MIN_MARGIN && used >= GREEN_MAX_USED) return 'warning'
  return 'success'
}

// the cells a meter's first line takes whole: title, figure, two spaces, detail
function widthOf(m: Meter) {
  const percent = m.percent ?? (typeof m.used === 'number' ? Math.round(m.used) + '%' : '—')
  return [...m.label].length + 1 + [...percent].length + 2 + [...m.detail].length
}

// two lines in one column: the title and the share used, the reset dimmed at the right; then the bar
function meter({ Box, Text, Svg }: any, gauge: string, cells: number, m: Meter) {
  const { key, label, used, elapsed, detail, ticks } = m
  const known = typeof used === 'number'
  const barStatus = m.barStatus ?? (known ? statusOf(used, elapsed) : null)
  const status = m.status !== undefined ? m.status : barStatus
  const percent = m.percent ?? (known ? Math.round(used) + '%' : '—')
  const hasFigure = m.percent !== undefined ? m.percent !== '—' : known
  const head = Box({
    flexDirection: 'row',
    justifyContent: 'space-between',
    columnGap: 1,
    children: [
      Box({
        flexDirection: 'row',
        columnGap: 1,
        flexShrink: 0,
        children: [Text({ bold: true, children: [label] }), Text({ bold: true, ...(hasFigure ? { color: textColor(status) } : { dimColor: true }), children: [percent] })],
      }),
      Text({ dimColor: true, wrap: 'truncate', children: [detail] }),
    ],
  })
  const bar =
    gauge === 'svg'
      ? Svg({
          source: svgBar(cells * PX_PER_COLUMN, known ? used : 0, elapsed, barStatus, ticks),
          alt: `${label} ${percent}${detail ? ', ' + detail : ''}${elapsed == null ? '' : ', ' + Math.round(elapsed) + '%'}`,
          width: cells * PX_PER_COLUMN,
          height: SVG_BAR_HEIGHT,
        })
      : textBar(Text, cells, known ? used : 0, elapsed, barStatus, ticks)
  const children = [head, bar]
  if (m.card && m.card.length > 0) children.push(hoverCard(Box, Text, m.card, cells))
  return Box({ key: 'meter-' + key, flexDirection: 'column', width: cells, flexShrink: 0, children })
}

// a card for the meter, drawn hidden and shown by the surface while the pointer is on the meter's
// keyed box: no hook runs. The desktop draws it as a floating card over the band, with its own border
function hoverCard(Box: any, Text: any, lines: string[], cells: number) {
  // no key of its own: a keyed Box is its own hover scope, and a hidden one can never be hovered
  return Box({
    position: 'absolute',
    top: 0,
    left: 0,
    width: Math.max(cells, CARD_MIN_CELLS),
    display: 'none',
    hover: { display: 'flex' },
    flexDirection: 'column',
    paddingX: 1,
    backgroundColor: CARD_BACKGROUND,
    children: lines.map((line, i) => Text({ key: `card-${i}`, wrap: 'wrap', ...(i === 0 ? { bold: true } : {}), children: [line] })),
  })
}

// used cells in the status color, the rest dim, and the time marker
function textBar(Text: any, cells: number, used: number, elapsed: number | null, status: string | null, ticks: number[] = []) {
  const filled = Math.round((clamp(used) / 100) * cells)
  // the cells of the cuts, shown on the unused part only
  const tickCells = new Set(ticks.map(f => Math.round(f * cells)))
  const marker = elapsed == null ? -1 : Math.min(cells - 1, Math.floor((elapsed / 100) * cells))
  const markerStyle = { color: MARKER_COLOR, bold: true }
  const usedStyle = status ? { color: textColor(status) } : { dimColor: true }
  const restStyle = { dimColor: true }
  const runs: { text: string; style: object }[] = []
  for (let i = 0; i < cells; i++) {
    const cell =
      i === marker
        ? { char: '┃', style: markerStyle }
        : i < filled
          ? { char: '█', style: usedStyle }
          : { char: tickCells.has(i) ? '┊' : '░', style: restStyle }
    const last = runs.at(-1)
    if (last && last.style === cell.style) last.text += cell.char
    else runs.push({ text: cell.char, style: cell.style })
  }
  return Text({ children: runs.map(run => Text({ ...run.style, children: [run.text] })) })
}

// a rounded track with the used share, thin cuts (each hour or day, or the context's upper tenths),
// and for a timed window a marker at the time gone
function svgBar(width: number, used: number, elapsed: number | null, status: string | null, ticks: number[] = []) {
  const height = SVG_BAR_HEIGHT
  const barH = 6
  const y = (height - barH) / 2
  const r = barH / 2
  const fill = Math.round((clamp(used) / 100) * width)
  const parts = [
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">`,
    `<clipPath id="c"><rect y="${y}" width="${width}" height="${barH}" rx="${r}"/></clipPath>`,
    `<g clip-path="url(#c)">`,
    `<rect y="${y}" width="${width}" height="${barH}" fill="${SVG_COLORS.track}"/>`,
  ]
  if (fill > 0) parts.push(`<rect y="${y}" width="${fill}" height="${barH}" fill="${SVG_COLORS[status ?? 'success']}"/>`)
  for (const f of ticks) parts.push(`<rect x="${(f * width - 0.5).toFixed(1)}" y="${y}" width="1" height="${barH}" fill="${SVG_COLORS.tick}"/>`)
  parts.push('</g>')
  if (elapsed != null) {
    const x = Math.min(width - 2, Math.max(0, Math.round((elapsed / 100) * width) - 1))
    parts.push(`<rect x="${x}" width="2" height="${height}" rx="1" fill="${SVG_COLORS.marker}"/>`)
  }
  parts.push('</svg>')
  return parts.join('')
}

// where the window's hours or days begin, as shares of the bar, the ends left out
function divisionPoints(divisions?: number) {
  if (!divisions || divisions < 2) return []
  return Array.from({ length: divisions - 1 }, (_, i) => (i + 1) / divisions)
}

// a palette's own hex, else the surface's theme colour of that name (success, warning, error)
function textColor(status: string | null) {
  if (!status) return undefined
  return usesPalette ? SVG_COLORS[status] : status
}

function clamp(percent: number) {
  return Math.min(Math.max(percent, 0), 100)
}

// the reset as HH:MM in timeZone, with the short weekday for the long windows ("mar. 09:00")
function resetClock(ms: number, showsDay: boolean) {
  const tag = locale === 'fr' ? 'fr-FR' : 'en-GB'
  try {
    const time = new Intl.DateTimeFormat(tag, { timeZone, hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(ms))
    if (!showsDay) return time
    return new Intl.DateTimeFormat(tag, { timeZone, weekday: 'short' }).format(new Date(ms)) + ' ' + time
  } catch {
    const d = new Date(ms)
    return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0')
  }
}

function untilReset(ms: number) {
  const minutes = Math.max(0, Math.ceil(ms / 60_000))
  const days = Math.floor(minutes / 1440)
  const hours = Math.floor((minutes % 1440) / 60)
  const dayUnit = locale === 'fr' ? 'j' : 'd'
  if (days > 0) return days + dayUnit + ' ' + hours + 'h'
  if (hours > 0) return hours + 'h' + String(minutes % 60).padStart(2, '0')
  return (minutes % 60) + ' min'
}

